1: 
2: const prefix=document.body.dataset.prefix, page=document.body.dataset.page;
3: const routes=['index','explore-cars','car-details','compare-cars','finance-calculator','test-drive','brands','brand-collection','new-arrivals','offers','reviews','saved-cars','about','contact','faq','admin','inventory','bookings'];
4: const names=['Home','Explore Cars','Car Details','Compare Cars','Finance Calculator','Book Test Drive','Explore Brands','Brand Collection','New Arrivals','Offers & Deals','Customer Reviews','Saved Cars','About Us','Contact Us','Help & FAQ','Admin Dashboard','Manage Inventory','Manage Bookings'];
5: const href=s=>s==='index'?prefix+'index.html':prefix+'pages/'+s+'.html';
6: const money=n=>'PKR '+Number(n||0).toLocaleString('en-PK');
7: const seed=[
8: {id:1,brand:'Porsche',model:'911 Carrera GTS',year:2025,price:69500000,engine:'3.6L Flat-Six',power:'532 HP',speed:'3.0 sec',type:'Coupe',tag:'Featured',img:'https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=1100&q=85'},
9: {id:2,brand:'Mercedes-Benz',model:'AMG GT',year:2025,price:58200000,engine:'4.0L V8',power:'577 HP',speed:'3.2 sec',type:'Coupe',tag:'New Arrival',img:'https://images.unsplash.com/photo-1618843479613-40f8afb4b4d8?auto=format&fit=crop&w=1100&q=85'},
10: {id:3,brand:'BMW',model:'M4 Competition',year:2025,price:41800000,engine:'3.0L Twin Turbo',power:'503 HP',speed:'3.4 sec',type:'Coupe',tag:'Popular',img:'https://images.unsplash.com/photo-1555215695-3004980ad54e?auto=format&fit=crop&w=1100&q=85'},
11: {id:4,brand:'Audi',model:'RS e-tron GT',year:2025,price:48700000,engine:'Dual Electric',power:'637 HP',speed:'3.1 sec',type:'Electric',tag:'Electric',img:'https://images.unsplash.com/photo-1606664515524-ed2f786a0bd6?auto=format&fit=crop&w=1100&q=85'},
12: {id:5,brand:'Lamborghini',model:'Huracán EVO',year:2024,price:114000000,engine:'5.2L V10',power:'631 HP',speed:'2.9 sec',type:'Supercar',tag:'Exclusive',img:'https://images.unsplash.com/photo-1544829099-b9a0c07fad1a?auto=format&fit=crop&w=1100&q=85'},
13: {id:6,brand:'Range Rover',model:'Sport Autobiography',year:2025,price:56500000,engine:'3.0L Turbo',power:'395 HP',speed:'5.4 sec',type:'SUV',tag:'Luxury SUV',img:'https://images.unsplash.com/photo-1519641471654-76ce0107ad1b?auto=format&fit=crop&w=1100&q=85'},
14: {id:7,brand:'Mercedes-Benz',model:'S-Class',year:2025,price:62500000,engine:'3.0L Hybrid',power:'442 HP',speed:'4.5 sec',type:'Sedan',tag:'Luxury',img:'https://images.unsplash.com/photo-1563720223185-11003d516935?auto=format&fit=crop&w=1100&q=85'},
15: {id:8,brand:'BMW',model:'i8 Roadster',year:2024,price:36900000,engine:'Hybrid',power:'369 HP',speed:'4.4 sec',type:'Roadster',tag:'Collector',img:'https://images.unsplash.com/photo-1523983388277-336a66bf9bcd?auto=format&fit=crop&w=1100&q=85'}
16: ];
17: const get=(k,d)=>{try{return JSON.parse(localStorage.getItem('apex_'+k))??d}catch{return d}};
18: const set=(k,v)=>localStorage.setItem('apex_'+k,JSON.stringify(v));
19: const cars=()=>get('cars',seed),wish=()=>get('wish',[]),bookings=()=>get('bookings',[]);
20: const car=id=>cars().find(x=>x.id===Number(id))||cars()[0];
21: const toast=t=>{document.querySelector('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.textContent=t;document.body.append(el);setTimeout(()=>el.remove(),2800)};
22: const toggleWish=id=>{let a=wish();a=a.includes(id)?a.filter(x=>x!==id):[...a,id];set('wish',a);toast(a.includes(id)?'Added to saved cars':'Removed from saved cars');render()};
23: const navLinks=[['index','Home'],['explore-cars','Explore Cars'],['brands','Brands'],['new-arrivals','New Arrivals'],['offers','Offers'],['about','About'],['contact','Contact']];
24: const header=()=>`<div class="topbar">THE ART OF AUTOMOTIVE EXCELLENCE · ISLAMABAD, PAKISTAN</div><header class="header"><div class="wrap nav"><a class="logo" href="${href('index')}">APEX<span>✦</span>MOTORS</a><nav class="navlinks" id="navlinks">${navLinks.map(([s,n])=>`<a class="${page===s?'active':''}" href="${href(s)}">${n}</a>`).join('')}<a href="${href('compare-cars')}">Compare</a><a href="${href('finance-calculator')}">Finance</a><a href="${href('test-drive')}">Test Drive</a><a href="${href('saved-cars')}">Saved Cars ♡</a><a href="${href('admin')}">Admin</a></nav><div class="nav-actions"><a class="btn small" href="${href('test-drive')}">Book a Test Drive ↗</a><button class="btn outline small menu-toggle" aria-label="Toggle navigation" onclick="document.getElementById('navlinks').classList.toggle('open')">☰ Menu</button></div></div></header>`;
25: const footer=()=>`<footer class="footer"><div class="wrap"><div class="footer-grid"><div><div class="logo">APEX<span>✦</span>MOTORS</div><p style="max-width:320px;margin-top:18px">An elevated way to discover, compare and experience the world's most extraordinary automobiles.</p><div class="eyebrow">DRIVE THE EXTRAORDINARY.</div></div><div><h4>Discover</h4>${[['explore-cars','Our Collection'],['brands','Our Brands'],['new-arrivals','New Arrivals'],['offers','Special Offers']].map(([s,n])=>`<a href="${href(s)}">${n}</a>`).join('')}</div><div><h4>Services</h4>${[['compare-cars','Compare Cars'],['finance-calculator','Finance'],['test-drive','Test Drive'],['saved-cars','Wishlist']].map(([s,n])=>`<a href="${href(s)}">${n}</a>`).join('')}</div><div><h4>Company</h4>${[['about','About Us'],['contact','Contact'],['faq','Help & FAQ'],['admin','Admin Portal']].map(([s,n])=>`<a href="${href(s)}">${n}</a>`).join('')}</div></div><div class="footer-bottom"><span>© 2026 APEX MOTORS. A luxury showroom concept website. Vehicle prices and availability are illustrative.</span><span>CRAFTED FOR THE EXTRAORDINARY</span></div></div></footer>`;
26: const hero=(title,desc,kicker='APEX MOTORS / THE COLLECTION')=>`<section class="page-hero"><div class="wrap"><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div></section>`;
27: const card=c=>`<article class="card"><div class="card-image"><a href="${href('car-details')}?id=${c.id}"><img src="${c.img}" alt="${c.brand} ${c.model}" loading="lazy"></a><span class="pill">${c.tag||'Available'}</span></div><div class="card-body"><div class="meta">${c.brand.toUpperCase()} / ${c.year} / ${c.type}</div><h3>${c.model}</h3><div class="meta">${c.engine} · ${c.power}</div><div class="card-bottom"><div><div class="meta">STARTING FROM</div><div class="price">${money(c.price)}</div></div><button class="btn ghost small" aria-label="Toggle saved car" onclick="toggleWish(${c.id})">${wish().includes(c.id)?'♥':'♡'}</button></div><div class="row" style="margin-top:18px"><a class="link" href="${href('car-details')}?id=${c.id}">View Details ↗</a><button class="btn outline small" onclick="addCompare(${c.id})">+ Compare</button></div></div></article>`;
28: const cards=a=>a.length?`<div class="grid">${a.map(card).join('')}</div>`:'<div class="empty">No vehicles found. Try changing your filters.</div>';
29: const section=(title,desc,body,alt=false)=>`<section class="section ${alt?'alt':''}"><div class="wrap"><div class="section-head"><div><div class="eyebrow">APEX MOTORS / CURATED FOR YOU</div><h2>${title}</h2></div><p>${desc}</p></div>${body}</div></section>`;
30: const home=()=>`<section class="hero"><div class="wrap hero-content"><div class="eyebrow">EST. 2026 · A NEW STANDARD OF LUXURY</div><h1>DRIVE THE<br><span class="gold">EXTRAORDINARY.</span></h1><p>Exceptional machines. Unforgettable journeys. Discover a curated collection of the world's most desirable automobiles.</p><div class="hero-actions"><a class="btn" href="${href('explore-cars')}">Explore Collection ↗</a><a class="btn outline" href="${href('test-drive')}">Book a Test Drive</a></div></div><div class="wrap hero-foot"><span>01 / THE PURSUIT OF PERFECTION</span><span>SCROLL TO EXPLORE ↓</span></div></section><div class="wrap grid four" style="margin-top:25px">${[['08+','Curated Vehicles'],['06','Luxury Marques'],['100%','Passion Driven'],['24/7','Digital Showroom']].map(x=>`<div class="stat"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('')}</div>${section('Icons of Excellence','A handpicked selection of extraordinary performance, craftsmanship and design.',cards(cars().slice(0,3))+'<div class="text-center" style="margin-top:35px"><a class="btn outline" href="'+href('explore-cars')+'">Explore All Vehicles ↗</a></div>')}${section('The World’s Finest Marques','Explore the brands that define the very pinnacle of automotive engineering.',`<div class="grid four">${['Porsche','Mercedes-Benz','BMW','Audi','Lamborghini','Range Rover'].map(b=>`<a class="brand-tile" href="${href('brand-collection')}?brand=${encodeURIComponent(b)}">${b}<div class="meta" style="margin-top:12px">EXPLORE ↗</div></a>`).join('')}</div>`,true)}<section class="banner"><div class="wrap"><div class="eyebrow">YOUR NEXT CHAPTER BEGINS HERE</div><h2>THE ROAD IS CALLING.</h2><p style="max-width:460px">Experience the difference behind the wheel. Schedule a private viewing or test drive today.</p><a class="btn" href="${href('test-drive')}">Reserve Your Experience ↗</a></div></section>${section('Why Choose APEX','Luxury is not only what you drive. It is how you feel at every step.',`<div class="grid">${[['✧','Curated Excellence','A carefully selected collection of remarkable automobiles.'],['◇','Personalized Experience','Discover vehicles tailored to your preferences and lifestyle.'],['↗','Seamless Journey','Compare, calculate and schedule your experience with ease.']].map(x=>`<div class="panel"><div class="number">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div>`)}<section class="section alt"><div class="wrap split"><div><div class="eyebrow">JOIN THE INNER CIRCLE</div><h2>Stay Ahead of the Curve.</h2><p>Receive exclusive news about upcoming arrivals and special offers.</p><form onsubmit="subscribe(event)" class="toolbar"><input type="email" required placeholder="Your email address" aria-label="Email address"><button class="btn">Subscribe ↗</button></form></div><img src="https://images.unsplash.com/photo-1493238792000-8113da705763?auto=format&fit=crop&w=1000&q=85" alt="Luxury sports car in a showroom" loading="lazy"></div></section>`;
31: const explore=()=>hero('The Collection.','Every extraordinary journey begins with an extraordinary vehicle.')+`<section class="section"><div class="wrap"><div class="toolbar"><input id="search" placeholder="Search make or model..." oninput="filterCars()"><select id="brand" onchange="filterCars()"><option value="">All Brands</option>${[...new Set(cars().map(c=>c.brand))].map(b=>`<option>${b}</option>`).join('')}</select><select id="type" onchange="filterCars()"><option value="">All Body Styles</option>${[...new Set(cars().map(c=>c.type))].map(t=>`<option>${t}</option>`).join('')}</select><select id="sort" onchange="filterCars()"><option value="">Featured First</option><option value="low">Price: Low to High</option><option value="high">Price: High to Low</option><option value="new">Newest First</option></select></div><div class="row"><p id="count">${cars().length} exceptional vehicles</p><a class="link" href="${href('compare-cars')}">Compare Selected ↗</a></div><div id="results">${cards(cars())}</div></div></section>`;
32: const details=()=>{let c=car(new URLSearchParams(location.search).get('id'));return hero(c.brand+' '+c.model,'Precision engineered. Passionately driven. Explore every detail.','THE COLLECTION / VEHICLE DETAILS')+`<section class="section"><div class="wrap details-layout"><div><img class="details-image" src="${c.img}" alt="${c.brand} ${c.model}"><div class="panel" style="margin-top:20px"><h3>About this vehicle</h3><p>Experience the signature craftsmanship, performance and unmistakable character of the ${c.brand} ${c.model}. Designed for those who demand more from every journey.</p></div></div><div><div class="eyebrow">${c.tag||'PREMIUM COLLECTION'}</div><h2>${c.model}</h2><p>${c.brand} · ${c.year} · ${c.type}</p><div class="price" style="font-size:32px;margin:25px 0">${money(c.price)}</div><div class="grid two">${[['Engine',c.engine],['Power',c.power],['0–100 KM/H',c.speed],['Model Year',c.year],['Body Style',c.type],['Availability','Inquire Now']].map(x=>`<div class="stat compact"><span>${x[0]}</span><h3 style="margin:10px 0 0">${x[1]}</h3></div>`).join('')}</div><div class="spacer"></div><div class="stack"><a class="btn" href="${href('test-drive')}?id=${c.id}">Book a Test Drive ↗</a><button class="btn outline" onclick="toggleWish(${c.id})">${wish().includes(c.id)?'♥ Remove from Wishlist':'♡ Save to Wishlist'}</button><button class="btn ghost" onclick="addCompare(${c.id})">+ Add to Comparison</button></div></div></div></section>${section('You May Also Like','Discover other remarkable vehicles from our collection.',cards(cars().filter(x=>x.id!==c.id).slice(0,3)),true)}`};
33: const addCompare=id=>{let a=get('compare',[]);if(!a.includes(id)){a=[...a,id].slice(-2);set('compare',a)}toast('Added to comparison')};
34: const compare=()=>{let a=get('compare',[1,3]);return hero('Compare Without Compromise.','Discover the differences that matter, side by side.')+`<section class="section"><div class="wrap"><div class="comparison">${[0,1].map(i=>`<div class="panel"><label>SELECT VEHICLE ${i+1}</label><select id="compare${i}" onchange="saveCompare()">${cars().map(c=>`<option value="${c.id}" ${c.id==a[i]?'selected':''}>${c.brand} ${c.model}</option>`).join('')}</select></div>`).join('')}</div><div id="compareResult"></div></div></section>`};
35: const renderComparison=()=>{let ids=[0,1].map(i=>Number(document.getElementById('compare'+i)?.value)),cs=ids.map(car),el=document.getElementById('compareResult');if(!el)return;el.innerHTML=`<div class="comparison" style="margin-top:25px">${cs.map(c=>`<div class="card"><img src="${c.img}" style="height:250px;width:100%;object-fit:cover" alt="${c.model}"><div class="card-body"><h3>${c.brand} ${c.model}</h3><div class="price">${money(c.price)}</div>${[['Year',c.year],['Engine',c.engine],['Power',c.power],['0–100 km/h',c.speed],['Body Style',c.type]].map(x=>`<div class="row" style="border-bottom:1px solid var(--line);padding:14px 0"><span class="muted">${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}<a class="btn" style="margin-top:20px" href="${href('car-details')}?id=${c.id}">View Vehicle ↗</a></div></div>`).join('')}</div>`};
36: const saveCompare=()=>{set('compare',[0,1].map(i=>Number(document.getElementById('compare'+i).value)));renderComparison()};
37: const finance=()=>hero('Finance Your Ambition.','Plan your purchase with a simple, transparent monthly payment estimate.')+`<section class="section"><div class="wrap details-layout"><div class="panel"><h3>Calculate Your Payment</h3><p>Adjust the values to see your estimated monthly installment.</p><div class="stack"><div><label>Vehicle Price (PKR)</label><input id="fprice" type="number" min="1" value="41800000" oninput="calcFinance()"></div><div><label>Down Payment (PKR)</label><input id="fdown" type="number" min="0" value="12000000" oninput="calcFinance()"></div><div><label>Annual Interest Rate (%)</label><input id="frate" type="number" min="0" max="100" step="0.1" value="12" oninput="calcFinance()"></div><div><label>Financing Period</label><select id="fyears" onchange="calcFinance()"><option value="2">2 Years</option><option value="3">3 Years</option><option value="4">4 Years</option><option value="5" selected>5 Years</option><option value="6">6 Years</option></select></div></div></div><div class="panel"><div class="eyebrow">YOUR ESTIMATED PAYMENT</div><div class="number" id="monthly">—</div><p>per month · indicative estimate only</p><div id="financeBreakdown"></div><p class="small-text">This is a demo calculator, not a financing offer. Actual rates, taxes, fees and lender terms may differ.</p><a class="btn" href="${href('contact')}">Request Consultation ↗</a></div></div></section>`;
38: const calcFinance=()=>{let price=+document.getElementById('fprice').value,down=+document.getElementById('fdown').value,r=+document.getElementById('frate').value/1200,n=+document.getElementById('fyears').value*12;let el=document.getElementById('monthly');if(price<=0||down<0||down>price||r<0){el.textContent='Invalid values';document.getElementById('financeBreakdown').innerHTML='<p class="gold">Please enter valid financing amounts.</p>';return}let principal=price-down,monthly=r?principal*r/(1-Math.pow(1+r,-n)):principal/n;el.textContent=money(Math.round(monthly));document.getElementById('financeBreakdown').innerHTML=[['Loan Amount',money(principal)],['Down Payment',money(down)],['Total Estimated Interest',money(Math.round(monthly*n-principal))],['Total Estimated Repayment',money(Math.round(monthly*n))]].map(x=>`<div class="row" style="border-bottom:1px solid var(--line);padding:14px 0"><span class="muted">${x[0]}</span><strong>${x[1]}</strong></div>`).join('')};
39: const selectCars=(id='vehicle',chosen)=>`<select id="${id}" required>${cars().map(c=>`<option value="${c.id}" ${c.id==chosen?'selected':''}>${c.brand} ${c.model}</option>`).join('')}</select>`;
40: const testDrive=()=>hero('Experience the Extraordinary.','The best way to know a vehicle is to feel it. Reserve your private test drive.')+`<section class="section"><div class="wrap details-layout"><div class="panel"><h3>Reserve Your Experience</h3><p>Complete the form below. This is a demo booking and is saved in your browser.</p><form class="form-grid" onsubmit="submitBooking(event)"><div><label>First Name *</label><input name="first" required minlength="2" placeholder="First name"></div><div><label>Last Name *</label><input name="last" required minlength="2" placeholder="Last name"></div><div><label>Email Address *</label><input name="email" type="email" required placeholder="you@example.com"></div><div><label>Phone Number *</label><input name="phone" required pattern="[0-9+() -]{9,18}" placeholder="03XX XXXXXXX"></div><div class="wide"><label>Choose Your Vehicle *</label>${selectCars('vehicle',new URLSearchParams(location.search).get('id'))}</div><div><label>Preferred Date *</label><input name="date" id="driveDate" type="date" required></div><div><label>Preferred Time *</label><select name="time" required><option value="">Select a time</option><option>10:00 AM</option><option>11:30 AM</option><option>01:00 PM</option><option>02:30 PM</option><option>04:00 PM</option></select></div><div class="wide"><label>Additional Notes</label><textarea name="notes" rows="3" placeholder="Anything we should know?"></textarea></div><div class="wide"><button class="btn" type="submit">Confirm Demo Booking ↗</button></div></form><div id="bookingMsg" aria-live="polite"></div></div><div><img src="https://images.unsplash.com/photo-1493238792000-8113da705763?auto=format&fit=crop&w=1100&q=85" alt="Sports car showroom" style="height:390px;width:100%;object-fit:cover"><div class="panel" style="margin-top:20px"><div class="eyebrow">THE APEX EXPERIENCE</div><h3>Your Journey, Your Pace.</h3><p>Choose your dream vehicle, select a convenient time and experience premium automotive engineering firsthand.</p><p class="small-text">Demo only: no actual appointment is sent to a dealership.</p></div></div></div></section>`;
41: const submitBooking=e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));if(new Date(d.date+'T23:59:59')<new Date()){document.getElementById('bookingMsg').innerHTML='<div class="notice error">Please select a future date.</div>';return}let b=bookings();b.push({...d,id:Date.now(),status:'Pending',car:car(d.vehicle).brand+' '+car(d.vehicle).model});set('bookings',b);f.reset();document.getElementById('bookingMsg').innerHTML='<div class="notice">Your demo booking has been recorded! Reference: APEX-'+b[b.length-1].id+'</div>'};
42: const brands=()=>hero('The Finest Marques.','Explore the automotive icons that inspire us.')+section('Explore Our Brands','Every marque brings its own philosophy of craftsmanship and performance.',`<div class="grid">${[...new Set(cars().map(c=>c.brand))].map(b=>`<a class="brand-tile" href="${href('brand-collection')}?brand=${encodeURIComponent(b)}"><div class="eyebrow">THE COLLECTION</div>${b}<p style="font-size:13px;margin:14px 0 0">${cars().filter(c=>c.brand===b).length} exceptional models</p><div class="link" style="margin-top:20px">Explore Brand ↗</div></a>`).join('')}</div>`);
43: const brandCollection=()=>{let b=new URLSearchParams(location.search).get('brand')||'Porsche',a=cars().filter(c=>c.brand===b);return hero(b+'.','Explore the precision, passion and performance behind this legendary marque.','APEX MOTORS / OUR MARQUES')+section('The '+b+' Collection','Curated models available in our digital showroom.',cards(a)+'<div style="margin-top:30px"><a class="btn outline" href="'+href('brands')+'">← All Brands</a></div>')};
44: const arrivals=()=>hero('What’s Next.','The latest additions to our ever-evolving collection.')+section('Freshly Arrived','Discover our newest standout models and next-generation performance.',cards(cars().filter(c=>c.year>=2025)))+`<section class="section alt"><div class="wrap split"><div><div class="eyebrow">FIND YOUR MATCH</div><h2>Which Drive Defines You?</h2><p>Take a quick quiz to discover your automotive personality.</p><label>What matters most to you?</label><select id="quiz"><option value="speed">Uncompromising performance</option><option value="luxury">Luxury and comfort</option><option value="eco">Modern electric technology</option><option value="suv">Versatility and space</option></select><button class="btn" style="margin-top:16px" onclick="recommend()">Find My Match ↗</button><div id="quizResult"></div></div><img src="https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=1000&q=85" alt="Performance sports car"></div></section>`;
45: const recommend=()=>{let m={speed:1,luxury:7,eco:4,suv:6},c=car(m[document.getElementById('quiz').value]);document.getElementById('quizResult').innerHTML=`<div class="notice">Your match: <strong>${c.brand} ${c.model}</strong> — <a href="${href('car-details')}?id=${c.id}"><u>View vehicle ↗</u></a></div>`};
46: const offers=()=>hero('Extraordinary Opportunities.','Discover exclusive promotional concepts for our digital showroom.')+section('Current Offers','Explore sample promotions and calculate your potential savings.',`<div class="grid">${[['WELCOME5','5% Off','An introductory showroom promotion concept.'],['APEX10','10% Off','A premium promotion concept for selected models.'],['VIP15','15% Off','A limited VIP promotion concept.']].map(x=>`<div class="panel"><div class="eyebrow">LIMITED OFFER / DEMO</div><h2>${x[1]}</h2><p>${x[2]}</p><div class="pill">CODE: ${x[0]}</div></div>`).join('')}</div>`)+`<section class="section alt"><div class="wrap details-layout"><div><div class="eyebrow">YOUR SAVINGS</div><h2>Discount Calculator.</h2><p>Enter a vehicle price and sample code to see the estimated savings.</p></div><div class="panel stack"><div><label>Vehicle Price (PKR)</label><input type="number" id="discountPrice" value="41800000" min="0"></div><div><label>Promo Code</label><input id="discountCode" placeholder="e.g. WELCOME5"></div><button class="btn" onclick="discount()">Apply Code ↗</button><div id="discountResult"></div></div></div></section>`;
47: const discount=()=>{let n=+document.getElementById('discountPrice').value,code=document.getElementById('discountCode').value.trim().toUpperCase(),rate={WELCOME5:.05,APEX10:.1,VIP15:.15}[code];document.getElementById('discountResult').innerHTML=n>0&&rate?`<div class="notice">You save ${money(n*rate)}. Estimated total: <strong>${money(n*(1-rate))}</strong></div>`:'<div class="notice error">Enter a valid price and promo code.</div>'};
48: const reviews=()=>{let r=get('reviews',[{name:'Ayesha K.',rating:5,comment:'Beautiful showroom experience and a seamless way to explore luxury cars.'},{name:'Hamza R.',rating:5,comment:'The comparison tool made choosing between models much easier.'},{name:'Sara M.',rating:4,comment:'Clean design and a very intuitive booking process.'}]);return hero('The APEX Experience.','Stories from our showroom community. Demo reviews shown below.')+section('What Drivers Are Saying','Explore visitor impressions and share your own.',`<div class="grid">${r.map(x=>`<div class="panel"><div class="review-stars">${'★'.repeat(x.rating)}${'☆'.repeat(5-x.rating)}</div><p style="margin-top:20px">“${escapeHtml(x.comment)}”</p><strong>${escapeHtml(x.name)}</strong></div>`).join('')}</div>`)+`<section class="section alt"><div class="wrap" style="max-width:750px"><div class="eyebrow">SHARE YOUR EXPERIENCE</div><h2>Leave a Review.</h2><form class="panel stack" onsubmit="submitReview(event)"><div><label>Your Name</label><input name="name" required minlength="2"></div><div><label>Rating</label><select name="rating" required><option value="5">★★★★★ Excellent</option><option value="4">★★★★ Very Good</option><option value="3">★★★ Good</option><option value="2">★★ Fair</option><option value="1">★ Poor</option></select></div><div><label>Your Review</label><textarea name="comment" required minlength="10" rows="4"></textarea></div><button class="btn">Submit Review ↗</button></form></div></section>`};
49: const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
50: const submitReview=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));let r=get('reviews',[]);r.push({...d,rating:+d.rating});set('reviews',r);toast('Review submitted');render()};
51: const saved=()=>hero('Your Private Collection.','Keep your favorite vehicles close. Your wishlist stays saved in this browser.')+section('Saved Vehicles','The extraordinary models you have chosen to remember.',cards(cars().filter(c=>wish().includes(c.id)))+'<div style="margin-top:28px"><a class="btn outline" href="'+href('explore-cars')+'">Explore More Vehicles ↗</a></div>');
52: const about=()=>hero('Driven by Passion.','A vision to make extraordinary automobiles more accessible to discover and experience.')+`<section class="section"><div class="wrap split"><img src="https://images.unsplash.com/photo-1493238792000-8113da705763?auto=format&fit=crop&w=1100&q=85" alt="Luxury automotive showroom"><div><div class="eyebrow">OUR STORY</div><h2>More Than a Showroom.</h2><p>APEX MOTORS is a fictional premium automotive showroom concept, built around a simple idea: the journey to your next car should be as inspiring as the car itself.</p><p>Our digital experience brings together carefully curated vehicles, clear specifications and thoughtful tools for discovery, comparison and planning.</p><a class="btn" href="${href('explore-cars')}">Discover the Collection ↗</a></div></div></section>${section('Our Guiding Principles','Everything we do is inspired by a passion for automotive excellence.',`<div class="grid">${[['01','Our Mission','Make discovering premium vehicles effortless, inspiring and informative.'],['02','Our Vision','Create a digital showroom experience that feels truly exceptional.'],['03','Our Promise','Clarity, elegant design and a seamless experience at every step.']].map(x=>`<div class="panel"><div class="number">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div>`,true)}`;
53: const contact=()=>hero('Let’s Connect.','Questions, inquiries or feedback? We would love to hear from you.')+`<section class="section"><div class="wrap details-layout"><div><div class="eyebrow">CONTACT OUR TEAM</div><h2>Every Great Journey Starts with a Conversation.</h2><p>This is a demo showroom. Contact form messages are stored locally in your browser, not sent to a real dealership.</p><div class="panel"><h3>Our Showroom Concept</h3><p>Islamabad, Pakistan</p><p>Opening Hours: Mon–Sat · 10:00 AM–7:00 PM (illustrative)</p><a class="link" href="${href('faq')}">Frequently Asked Questions ↗</a></div></div><form class="panel form-grid" onsubmit="submitContact(event)"><div><label>Your Name *</label><input name="name" required minlength="2"></div><div><label>Email *</label><input type="email" name="email" required></div><div class="wide"><label>Subject *</label><select name="subject" required><option>General Inquiry</option><option>Vehicle Availability</option><option>Test Drive</option><option>Financing</option></select></div><div class="wide"><label>Message *</label><textarea name="message" required minlength="10" rows="6"></textarea></div><div class="wide"><button class="btn">Send Demo Message ↗</button><p class="small-text">No email will actually be sent.</p></div></form></div></section>`;
54: const submitContact=e=>{e.preventDefault();let a=get('messages',[]);a.push(Object.fromEntries(new FormData(e.target)));set('messages',a);e.target.reset();toast('Message saved locally')};
55: const faq=()=>hero('Here to Help.','Answers to common questions about discovering and experiencing our vehicles.')+`<section class="section"><div class="wrap details-layout"><div><div class="eyebrow">FREQUENTLY ASKED QUESTIONS</div><h2>Everything You Need to Know.</h2><p>Find answers to questions about our collection, demo bookings and ownership planning.</p><a class="btn" href="${href('contact')}">Still Have Questions? ↗</a></div><div class="panel">${[['How do I book a test drive?','Select a vehicle and complete the test-drive form. This concept website stores demo bookings in your browser.'],['Can I compare two vehicles?','Yes. Add vehicles to the comparison list or select them on the Compare Cars page.'],['Are the displayed prices final?','No. All prices are illustrative sample values for this academic showroom concept.'],['How does the finance calculator work?','It estimates monthly payments using the loan amount, annual interest rate and duration.'],['Where are my saved cars stored?','Your wishlist is stored locally in this browser using localStorage.'],['Can I purchase a vehicle here?','No. This is a demonstration showroom website, not a live dealership.']].map(x=>`<details class="faq-item"><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div></div></section><section class="section alt"><div class="wrap details-layout"><div><div class="eyebrow">OWNERSHIP PLANNING</div><h2>Estimate Your Annual Costs.</h2><p>Adjust the figures to get a rough estimate of annual running costs.</p></div><div class="panel stack"><div><label>Monthly Fuel / Charging Cost (PKR)</label><input id="fuel" type="number" value="40000" min="0"></div><div><label>Annual Insurance (PKR)</label><input id="insurance" type="number" value="250000" min="0"></div><div><label>Annual Maintenance (PKR)</label><input id="maintenance" type="number" value="180000" min="0"></div><button class="btn" onclick="ownership()">Calculate Annual Cost ↗</button><div id="ownershipResult"></div></div></div></section>`;
56: const ownership=()=>{let a=['fuel','insurance','maintenance'].map(id=>+document.getElementById(id).value);document.getElementById('ownershipResult').innerHTML=a.some(x=>x<0)?'<div class="notice error">Costs cannot be negative.</div>':`<div class="notice">Estimated yearly running cost: <strong>${money(a[0]*12+a[1]+a[2])}</strong></div>`};
57: const admin=()=>{let b=bookings(),c=cars();return hero('The Command Center.','Your showroom, at a glance. All data is local to this browser.','APEX MOTORS / ADMIN')+`<section class="section"><div class="wrap"><div class="grid four">${[[c.length,'Total Vehicles'],[b.length,'Total Bookings'],[b.filter(x=>x.status==='Pending').length,'Pending Requests'],[b.filter(x=>x.status==='Approved').length,'Approved Bookings']].map(x=>`<div class="stat"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('')}</div><div class="grid two" style="margin-top:28px"><a class="panel" href="${href('inventory')}"><div class="eyebrow">SHOWROOM OPERATIONS</div><h2>Manage Inventory ↗</h2><p>Add, edit and remove vehicles in your local demo catalogue.</p></a><a class="panel" href="${href('bookings')}"><div class="eyebrow">CUSTOMER EXPERIENCES</div><h2>Manage Bookings ↗</h2><p>Review and update test-drive requests.</p></a></div><div class="panel" style="margin-top:28px"><h3>Collection by Brand</h3>${[...new Set(c.map(x=>x.brand))].map(brand=>`<div class="row"><span>${brand}</span><strong>${c.filter(x=>x.brand===brand).length} vehicles</strong></div><div class="progress"><span style="width:${c.filter(x=>x.brand===brand).length/c.length*100}%"></span></div>`).join('')}</div></div></section>`};
58: const inventory=()=>hero('Manage Inventory.','Add, edit or remove vehicles. Changes are saved locally.','APEX MOTORS / ADMIN')+`<section class="section"><div class="wrap"><div class="panel"><h3 id="inventoryHeading">Add Vehicle</h3><form id="inventoryForm" class="form-grid" onsubmit="saveVehicle(event)"><input type="hidden" name="id" id="editId"><div><label>Brand *</label><input name="brand" required></div><div><label>Model *</label><input name="model" required></div><div><label>Price (PKR) *</label><input type="number" name="price" min="1" required></div><div><label>Year *</label><input type="number" name="year" min="1990" max="2035" required></div><div><label>Engine *</label><input name="engine" required></div><div><label>Power *</label><input name="power" required></div><div><label>0–100 km/h *</label><input name="speed" required></div><div><label>Body Type *</label><input name="type" required></div><div class="wide"><label>Image URL *</label><input name="img" type="url" required placeholder="https://..."></div><div class="wide"><button class="btn">Save Vehicle ↗</button> <button type="reset" class="btn ghost" onclick="document.getElementById('editId').value='';document.getElementById('inventoryHeading').textContent='Add Vehicle'">Clear</button></div></form></div><div class="panel" style="margin-top:30px"><h3>Current Inventory</h3><div class="table-scroll"><table class="table"><thead><tr><th>Vehicle</th><th>Year</th><th>Price</th><th>Actions</th></tr></thead><tbody>${cars().map(c=>`<tr><td>${escapeHtml(c.brand)} ${escapeHtml(c.model)}</td><td>${c.year}</td><td>${money(c.price)}</td><td><button class="btn small outline" onclick="editVehicle(${c.id})">Edit</button> <button class="btn small ghost" onclick="deleteVehicle(${c.id})">Delete</button></td></tr>`).join('')}</tbody></table></div></div></div></section>`;
59: const saveVehicle=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),a=cars();d.price=Number(d.price);d.year=Number(d.year);d.id=d.id?Number(d.id):Date.now();d.tag='Available';if(a.some(c=>c.id===d.id))a=a.map(c=>c.id===d.id?d:c);else a.push(d);set('cars',a);toast('Vehicle saved');render()};
60: const editVehicle=id=>{let c=car(id),f=document.getElementById('inventoryForm');Object.keys(c).forEach(k=>{if(f.elements[k])f.elements[k].value=c[k]});document.getElementById('inventoryHeading').textContent='Edit Vehicle';window.scrollTo({top:0,behavior:'smooth'})};
61: const deleteVehicle=id=>{if(confirm('Remove this vehicle from inventory?')){set('cars',cars().filter(c=>c.id!==id));toast('Vehicle removed');render()}};
62: const manageBookings=()=>hero('Manage Bookings.','Review and manage customer test-drive requests.','APEX MOTORS / ADMIN')+`<section class="section"><div class="wrap"><div class="panel"><div class="row"><h3>Booking Records</h3><span class="pill">${bookings().length} Requests</span></div><div class="table-scroll"><table class="table"><thead><tr><th>Customer</th><th>Vehicle</th><th>Date / Time</th><th>Status</th><th>Actions</th></tr></thead><tbody>${bookings().length?bookings().map(b=>`<tr><td>${escapeHtml(b.first)} ${escapeHtml(b.last)}<div class="meta">${escapeHtml(b.email)}</div></td><td>${escapeHtml(b.car)}</td><td>${b.date}<div class="meta">${b.time}</div></td><td><span class="pill">${b.status}</span></td><td><select aria-label="Update booking status" onchange="updateBooking(${b.id},this.value)">${['Pending','Approved','Rejected','Completed'].map(s=>`<option ${b.status===s?'selected':''}>${s}</option>`).join('')}</select><button class="btn small ghost" onclick="removeBooking(${b.id})">Delete</button></td></tr>`).join(''):'<tr><td colspan="5" class="muted">No test-drive bookings yet. Submit a demo booking to see it here.</td></tr>'}</tbody></table></div></div></div></section>`;
63: const updateBooking=(id,status)=>{set('bookings',bookings().map(b=>b.id===id?{...b,status}:b));toast('Booking status updated');render()};
64: const removeBooking=id=>{if(confirm('Delete this booking?')){set('bookings',bookings().filter(b=>b.id!==id));render()}};
65: const views={'index':home,'explore-cars':explore,'car-details':details,'compare-cars':compare,'finance-calculator':finance,'test-drive':testDrive,'brands':brands,'brand-collection':brandCollection,'new-arrivals':arrivals,'offers':offers,'reviews':reviews,'saved-cars':saved,'about':about,'contact':contact,'faq':faq,'admin':admin,'inventory':inventory,'bookings':manageBookings};
66: function render(){document.getElementById('app').innerHTML=header()+(views[page]||home)()+footer();if(page==='compare-cars')renderComparison();if(page==='finance-calculator')calcFinance();if(page==='test-drive'){document.getElementById('driveDate').min=new Date().toLocaleDateString('en-CA')}}
67: function filterCars(){let q=document.getElementById('search').value.toLowerCase(),b=document.getElementById('brand').value,t=document.getElementById('type').value,s=document.getElementById('sort').value;let a=cars().filter(c=>(c.brand+' '+c.model).toLowerCase().includes(q)&&(!b||c.brand===b)&&(!t||c.type===t));if(s==='low')a.sort((x,y)=>x.price-y.price);if(s==='high')a.sort((x,y)=>y.price-x.price);if(s==='new')a.sort((x,y)=>y.year-x.year);document.getElementById('results').innerHTML=cards(a);document.getElementById('count').textContent=a.length+' exceptional vehicles'}
68: function subscribe(e){e.preventDefault();let email=e.target.querySelector('input').value,a=get('subscribers',[]);if(!a.includes(email))a.push(email);set('subscribers',a);e.target.reset();toast('Subscribed to demo newsletter')}
69: render();

