/* ==========================================================================
   CAR VAULT — Shared Theme & Layout Styles (css/common.css)
   Theme Colors: Dark Navy (#111827), Gold (#D9A441), White (#FFFFFF), Light Grey (#F3F4F6)
   ========================================================================== */

:root {
  --navy: #111827;
  --navy-dark: #0b101b;
  --navy-light: #1f2937;
  --gold: #d9a441;
  --gold-hover: #c28e2e;
  --gold-soft: #fdf6e7;
  --white: #ffffff;
  --light-grey: #f3f4f6;
  --border-grey: #e5e7eb;
  --text-dark: #111827;
  --text-muted: #4b5563;
  --success-bg: #ecfdf5;
  --success-border: #10b981;
  --success-text: #065f46;
  --error-bg: #fef2f2;
  --error-border: #ef4444;
  --error-text: #991b1b;
  --shadow-sm: 0 2px 8px rgba(17, 24, 39, 0.06);
  --shadow-md: 0 10px 25px rgba(17, 24, 39, 0.1);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-pill: 999px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: "DM Sans", "Segoe UI", Arial, sans-serif;
  background-color: var(--light-grey);
  color: var(--text-dark);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

main {
  flex: 1;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select {
  font-family: inherit;
  font-size: 1rem;
}

/* Visible focus state for keyboard accessibility */
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 3px solid var(--gold);
  outline-offset: 2px;
}

.container {
  width: min(1200px, calc(100% - 32px));
  margin: 0 auto;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-pill);
  font-weight: 700;
  font-size: 0.95rem;
  border: 2px solid transparent;
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease, transform 0.15s ease, border-color 0.2s ease;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn-primary {
  background-color: var(--gold);
  color: var(--navy);
  border-color: var(--gold);
}

.btn-primary:hover {
  background-color: var(--gold-hover);
  border-color: var(--gold-hover);
}

.btn-navy {
  background-color: var(--navy);
  color: var(--white);
  border-color: var(--navy);
}

.btn-navy:hover {
  background-color: var(--navy-light);
}

.btn-outline {
  background-color: var(--white);
  color: var(--navy);
  border-color: var(--navy);
}

.btn-outline:hover {
  background-color: var(--navy);
  color: var(--white);
}

.btn-outline.is-active {
  background-color: var(--gold-soft);
  border-color: var(--gold);
  color: var(--navy);
}

/* ---------- Header & Navbar ---------- */
.site-header {
  background-color: var(--navy);
  color: var(--white);
  border-bottom: 3px solid var(--gold);
  position: sticky;
  top: 0;
  z-index: 100;
}

.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 72px;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.15rem;
  letter-spacing: 0.1em;
  color: var(--white);
  white-space: nowrap;
}

.brand-logo img {
  width: 38px;
  height: 38px;
  border-radius: 6px;
  object-fit: cover;
  border: 1px solid var(--gold);
}

.brand-logo span {
  color: var(--gold);
}

.nav-links {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  list-style: none;
}

.nav-links a,
.nav-links button.nav-action-link {
  background: none;
  border: none;
  color: #e5e7eb;
  font-size: 0.85rem;
  font-weight: 600;
  padding: 6px 4px;
  cursor: pointer;
  white-space: nowrap;
  transition: color 0.2s ease;
}

.nav-links a:hover,
.nav-links a.active,
.nav-links button.nav-action-link:hover {
  color: var(--gold);
}

.nav-links a.active {
  border-bottom: 2px solid var(--gold);
}

.saved-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: var(--gold);
  color: var(--navy);
  font-size: 0.72rem;
  font-weight: 800;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: var(--radius-pill);
  margin-left: 4px;
}

.mobile-controls {
  display: none;
  align-items: center;
  gap: 10px;
}

.menu-toggle {
  background-color: var(--navy-light);
  color: var(--white);
  border: 1px solid var(--gold);
  border-radius: var(--radius-sm);
  padding: 7px 12px;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
}

/* ---------- Shared Car Card ---------- */
.car-card {
  background-color: var(--white);
  border: 1px solid var(--border-grey);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  display: flex;
  flex-direction: column;
}

.car-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: var(--gold);
}

.car-card-link {
  display: block;
  flex: 1;
}

.car-card-image-wrap {
  position: relative;
  height: 220px;
  background-color: var(--navy);
  overflow: hidden;
}

.car-card-image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.car-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background-color: var(--navy);
  color: var(--gold);
  border: 1px solid var(--gold);
  padding: 4px 10px;
  border-radius: var(--radius-pill);
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.car-card-body {
  padding: 18px 20px;
}

.car-card-meta {
  font-size: 0.8rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.car-card-title {
  font-size: 1.2rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 6px;
}

.car-card-price {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--gold-hover);
}

.car-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-top: 1px solid var(--border-grey);
  background-color: #fafafa;
}

.card-details-cta {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--navy);
}

.card-details-cta:hover {
  color: var(--gold-hover);
}

.icon-wish-btn {
  background: var(--white);
  border: 1px solid var(--border-grey);
  border-radius: var(--radius-pill);
  padding: 5px 12px;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--navy);
  cursor: pointer;
  transition: all 0.2s ease;
}

.icon-wish-btn.saved {
  background-color: var(--gold-soft);
  border-color: var(--gold);
  color: var(--navy);
}

/* ---------- Footer ---------- */
.site-footer {
  background-color: var(--navy);
  color: #d1d5db;
  border-top: 3px solid var(--gold);
  padding: 44px 0 24px;
  margin-top: 48px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 28px;
  margin-bottom: 28px;
}

.footer-col h3,
.footer-col h4 {
  color: var(--white);
  font-size: 1rem;
  margin-bottom: 12px;
}

.footer-col p {
  font-size: 0.9rem;
  color: #9ca3af;
}

.footer-col ul {
  list-style: none;
  display: grid;
  gap: 8px;
}

.footer-col a {
  font-size: 0.9rem;
